/**
 * The framework templates for `chatly init` (CHT-F02).
 *
 * Every API a generated file uses is in a PUBLISHED package at the version on
 * npm today — `chatlyUserHash` from `@chatlychat/widget-react/server`,
 * `<ChatlyLauncher>`'s `externalId`/`userHash`/`getToken` props, and
 * `Chatly('identify', …)` on the snippet. A template that imported something
 * from a working tree would scaffold a project that does not install.
 *
 * ═══ THE ONE THING A WIZARD CANNOT KNOW ═══════════════════════════════════
 *
 * Who is signed in. Every identity route below has a `currentUserId` stub
 * that answers `null`, so a freshly scaffolded app runs with every visitor
 * ANONYMOUS — never with an unsigned claim. Wiring it to the integrator's
 * auth is the step the summary names first.
 */
import { cspModule, privacyTable, type ScaffoldFile, type ScaffoldInput } from './shared.js';

export const FRAMEWORKS = ['next', 'remix', 'astro', 'express'] as const;
export type Framework = (typeof FRAMEWORKS)[number];

/**
 * The frameworks with no `--identity atlas` output. An Atlas token is minted
 * in the browser, so there is no server half to generate, and these two have
 * no React component to pass `getToken` to — the page calls
 * `Chatly('identify', { getToken })` itself.
 */
export const NO_ATLAS: ReadonlyArray<Framework> = ['express', 'astro'];

const IDENTITY_ROUTE_NEXT = (input: ScaffoldInput): string => `/**
 * Chatly identity verification (HMAC) for web channel ${input.publicId}.
 * Generated by \`chatly init next\` on ${input.generatedOn}.
 *
 * Signs the signed-in user's id with the channel's IDV secret, so the widget
 * can prove who the visitor is. The secret stays on this server:
 * \`@chatlychat/widget-react/server\` refuses to run in a browser bundle.
 *
 * Wire \`currentUserId\` to your auth before shipping. Until then it answers
 * \`{ identity: null }\` and every visitor chats anonymously.
 */
import { chatlyUserHash } from '@chatlychat/widget-react/server';
import { NextResponse } from 'next/server';

export const dynamic = 'force-dynamic';

const NO_STORE = { 'cache-control': 'no-store' };

/** TODO: return the signed-in user's stable id from your auth library, or null. */
async function currentUserId(): Promise<string | null> {
  return null;
}

export async function GET(): Promise<NextResponse> {
  const externalId = await currentUserId();
  if (externalId === null) {
    return NextResponse.json({ identity: null }, { headers: NO_STORE });
  }
  const secret = process.env.CHATLY_IDV_SECRET;
  if (secret === undefined || secret === '') {
    // Loud rather than anonymous: a signed-in user silently chatting as a
    // stranger is a misconfiguration nobody would notice.
    return NextResponse.json(
      { error: 'CHATLY_IDV_SECRET is not set on the server' },
      { status: 500, headers: NO_STORE },
    );
  }
  return NextResponse.json(
    { identity: { externalId, userHash: chatlyUserHash(secret, externalId) } },
    { headers: NO_STORE },
  );
}
`;

const LAUNCHER_NEXT_HMAC = (input: ScaffoldInput): string => `'use client';
/**
 * The Chatly launcher for web channel ${input.publicId}, identified through
 * \`app/api/chatly/identity/route.ts\`. Generated by \`chatly init next\` on
 * ${input.generatedOn}. Render <Chatly /> once, in your root layout.
 */
import { ChatlyLauncher } from '@chatlychat/widget-react';
import { useEffect, useState } from 'react';

interface Identity {
  readonly externalId: string;
  readonly userHash: string;
}

export function Chatly() {
  // undefined = still asking; null = anonymous.
  const [identity, setIdentity] = useState<Identity | null | undefined>(undefined);

  useEffect(() => {
    let live = true;
    fetch('/api/chatly/identity', { cache: 'no-store' })
      .then(async (r) => (r.ok ? ((await r.json()) as { identity: Identity | null }) : { identity: null }))
      .then((body) => live && setIdentity(body.identity))
      .catch(() => live && setIdentity(null));
    return () => {
      live = false;
    };
  }, []);

  // Rendered only once the identity is known, so the widget starts as the
  // right visitor instead of starting anonymous and switching.
  if (identity === undefined) {
    return null;
  }
  return <ChatlyLauncher publicId=${JSON.stringify(input.publicId)} {...(identity ?? {})} />;
}
`;

const LAUNCHER_NEXT_ATLAS = (input: ScaffoldInput): string => `'use client';
/**
 * The Chatly launcher for web channel ${input.publicId}, identified with an
 * Atlas token (\`identityVerification.mode: 'atlas'\`). Generated by
 * \`chatly init next --identity atlas\` on ${input.generatedOn}.
 *
 * Pass \`getToken\` for a signed-in user and leave it out for a signed-out one:
 *
 *   <Chatly getToken={() => atlas.session.getToken({ template: 'chatly' })} />
 *
 * The template and the channel setting it must match are on
 * https://chatlychat.com/guides/identity-verification#worked-example-an-atlas-instance-on-the-shared-host
 */
import { ChatlyLauncher } from '@chatlychat/widget-react';

export function Chatly({ getToken }: { getToken?: () => Promise<string> }) {
  return (
    <ChatlyLauncher
      publicId=${JSON.stringify(input.publicId)}
      {...(getToken === undefined ? {} : { getToken })}
    />
  );
}
`;

const IDENTITY_EXPRESS = (input: ScaffoldInput): string => `/**
 * Chatly identity verification (HMAC) for web channel ${input.publicId}.
 * Generated by \`chatly init express\` on ${input.generatedOn}.
 *
 *   import { chatlyIdentity } from './chatly/identity.mjs';
 *   app.get('/api/chatly/identity', chatlyIdentity((req) => req.user?.id ?? null));
 *
 * \`userIdOf\` is the one thing to write: return the signed-in user's stable id,
 * or null for a signed-out visitor, who then chats anonymously.
 */
import { createHmac } from 'node:crypto';

/** HMAC-SHA256(secret, externalId), hex — what the widget sends as userHash. */
export function chatlyUserHash(secret, externalId) {
  return createHmac('sha256', secret).update(externalId).digest('hex');
}

/** @param {(req: any) => string | null | Promise<string | null>} userIdOf */
export function chatlyIdentity(userIdOf) {
  return async (req, res) => {
    res.set('cache-control', 'no-store');
    const externalId = await userIdOf(req);
    if (externalId === null || externalId === undefined) {
      return res.json({ identity: null });
    }
    const secret = process.env.CHATLY_IDV_SECRET;
    if (!secret) {
      return res.status(500).json({ error: 'CHATLY_IDV_SECRET is not set on the server' });
    }
    return res.json({ identity: { externalId, userHash: chatlyUserHash(secret, externalId) } });
  };
}
`;

const SNIPPET_EXPRESS = (input: ScaffoldInput): string => `<!--
  Chatly for web channel ${input.publicId}. Generated by \`chatly init express\`
  on ${input.generatedOn}. Paste before </body>. The first script is the
  channel's own embed snippet; the second identifies a signed-in visitor
  through /api/chatly/identity (see chatly/identity.mjs).
-->
${input.embed.snippet}
<script>
  fetch('/api/chatly/identity', { cache: 'no-store' })
    .then(function (r) { return r.ok ? r.json() : { identity: null }; })
    .then(function (body) { if (body.identity) Chatly('identify', body.identity); })
    .catch(function () {});
</script>
`;

/**
 * The Remix loader imports nothing from Remix or React Router on purpose. A
 * `LoaderFunctionArgs` import would pin the file to `@remix-run/node` (Remix
 * v2) or to `react-router` (v7 framework mode), and a loader that takes
 * `{ request }` and returns a `Response` is a valid loader in both.
 */
const IDENTITY_ROUTE_REMIX = (input: ScaffoldInput): string => `/**
 * Chatly identity verification (HMAC) for web channel ${input.publicId}.
 * Generated by \`chatly init remix\` on ${input.generatedOn}.
 *
 * A resource route (a loader and no component), served at
 * /api/chatly/identity by Remix v2's flat routes and by React Router v7's
 * \`flatRoutes()\`. Signs the signed-in user's id with the channel's IDV
 * secret, so the widget can prove who the visitor is. The secret stays on
 * this server: a loader never reaches the browser bundle, and
 * \`@chatlychat/widget-react/server\` refuses to run in one anyway.
 *
 * Wire \`currentUserId\` to your auth before shipping. Until then it answers
 * \`{ identity: null }\` and every visitor chats anonymously.
 */
import { chatlyUserHash } from '@chatlychat/widget-react/server';

const HEADERS = { 'content-type': 'application/json', 'cache-control': 'no-store' };

/** TODO: return the signed-in user's stable id from your session, or null. */
async function currentUserId(request: Request): Promise<string | null> {
  void request;
  return null;
}

export async function loader({ request }: { request: Request }): Promise<Response> {
  const externalId = await currentUserId(request);
  if (externalId === null) {
    return new Response(JSON.stringify({ identity: null }), { headers: HEADERS });
  }
  const secret = process.env.CHATLY_IDV_SECRET;
  if (secret === undefined || secret === '') {
    // Loud rather than anonymous: a signed-in user silently chatting as a
    // stranger is a misconfiguration nobody would notice.
    return new Response(JSON.stringify({ error: 'CHATLY_IDV_SECRET is not set on the server' }), {
      status: 500,
      headers: HEADERS,
    });
  }
  return new Response(
    JSON.stringify({ identity: { externalId, userHash: chatlyUserHash(secret, externalId) } }),
    { headers: HEADERS },
  );
}
`;

/**
 * Remix's launcher is Next's without `'use client'` and with its own header:
 * every Remix component renders on the server and hydrates, and the identity
 * fetch is in an effect, so it runs in the browser only.
 */
const LAUNCHER_REMIX_HMAC = (input: ScaffoldInput): string =>
  LAUNCHER_NEXT_HMAC(input)
    .replace(/^'use client';\n/, '')
    .replace('`app/api/chatly/identity/route.ts`', '`app/routes/api.chatly.identity.ts`')
    .replace('`chatly init next`', '`chatly init remix`')
    .replace('in your root layout', 'in app/root.tsx');

const LAUNCHER_REMIX_ATLAS = (input: ScaffoldInput): string =>
  LAUNCHER_NEXT_ATLAS(input)
    .replace(/^'use client';\n/, '')
    .replace('`chatly init next --identity atlas`', '`chatly init remix --identity atlas`');

/**
 * Astro's endpoint signs with `node:crypto`, like Express's, rather than
 * importing `@chatlychat/widget-react/server`: an Astro site has no reason to
 * install a React package, and the construction is one line.
 */
const IDENTITY_ROUTE_ASTRO = (input: ScaffoldInput): string => `/**
 * Chatly identity verification (HMAC) for web channel ${input.publicId}.
 * Generated by \`chatly init astro\` on ${input.generatedOn}.
 *
 * Served at /api/chatly/identity. \`prerender = false\` makes it run per
 * request, which needs a server adapter with Node built-ins
 * (\`@astrojs/node\`, or another adapter with \`node:crypto\`): a prerendered
 * identity would be one visitor's answer frozen into a static file.
 *
 * Wire \`currentUserId\` to your auth before shipping. Until then it answers
 * \`{ identity: null }\` and every visitor chats anonymously.
 */
import { createHmac } from 'node:crypto';

import type { APIRoute } from 'astro';

export const prerender = false;

const HEADERS = { 'content-type': 'application/json', 'cache-control': 'no-store' };

/** HMAC-SHA256(secret, externalId), hex — what the widget sends as userHash. */
export function chatlyUserHash(secret: string, externalId: string): string {
  return createHmac('sha256', secret).update(externalId).digest('hex');
}

/** TODO: return the signed-in user's stable id (from \`locals\`, a cookie, …), or null. */
async function currentUserId(context: Parameters<APIRoute>[0]): Promise<string | null> {
  void context;
  return null;
}

export const GET: APIRoute = async (context) => {
  const externalId = await currentUserId(context);
  if (externalId === null) {
    return new Response(JSON.stringify({ identity: null }), { headers: HEADERS });
  }
  const secret = process.env.CHATLY_IDV_SECRET;
  if (secret === undefined || secret === '') {
    // Loud rather than anonymous: a signed-in user silently chatting as a
    // stranger is a misconfiguration nobody would notice.
    return new Response(JSON.stringify({ error: 'CHATLY_IDV_SECRET is not set on the server' }), {
      status: 500,
      headers: HEADERS,
    });
  }
  return new Response(
    JSON.stringify({ identity: { externalId, userHash: chatlyUserHash(secret, externalId) } }),
    { headers: HEADERS },
  );
};
`;

/**
 * The snippet is a string in the frontmatter and rendered with `set:html`, not
 * pasted into the template: a bare `<script>` in an `.astro` file is bundled
 * and turned into a module, which would move the shim off `window` and out of
 * order. `set:html` emits it byte for byte, and `is:inline` does the same for
 * the identify call.
 */
const COMPONENT_ASTRO = (input: ScaffoldInput): string => `---
/**
 * Chatly for web channel ${input.publicId}. Generated by \`chatly init astro\`
 * on ${input.generatedOn}. Render <Chatly /> once, before </body> in your
 * layout. The first script is the channel's own embed snippet; the second
 * identifies a signed-in visitor through /api/chatly/identity
 * (src/pages/api/chatly/identity.ts).
 */
const snippet = ${JSON.stringify(input.embed.snippet)};
---

<Fragment set:html={snippet} />
<script is:inline>
  fetch('/api/chatly/identity', { cache: 'no-store' })
    .then(function (r) { return r.ok ? r.json() : { identity: null }; })
    .then(function (body) { if (body.identity) Chatly('identify', body.identity); })
    .catch(function () {});
</script>
`;

/** Every file `chatly init <framework>` writes, in the order it reports them. */
export function scaffold(framework: Framework, input: ScaffoldInput): ReadonlyArray<ScaffoldFile> {
  const common = [cspModule(input), privacyTable(input)];
  if (framework === 'next') {
    return [
      ...(input.identity === 'hmac'
        ? [{ path: 'app/api/chatly/identity/route.ts', contents: IDENTITY_ROUTE_NEXT(input) }]
        : []),
      {
        path: 'components/chatly.tsx',
        contents:
          input.identity === 'hmac' ? LAUNCHER_NEXT_HMAC(input) : LAUNCHER_NEXT_ATLAS(input),
      },
      ...common,
    ];
  }
  if (framework === 'remix') {
    return [
      ...(input.identity === 'hmac'
        ? [{ path: 'app/routes/api.chatly.identity.ts', contents: IDENTITY_ROUTE_REMIX(input) }]
        : []),
      {
        path: 'app/components/chatly.tsx',
        contents:
          input.identity === 'hmac' ? LAUNCHER_REMIX_HMAC(input) : LAUNCHER_REMIX_ATLAS(input),
      },
      ...common,
    ];
  }
  if (framework === 'astro') {
    return [
      { path: 'src/pages/api/chatly/identity.ts', contents: IDENTITY_ROUTE_ASTRO(input) },
      { path: 'src/components/Chatly.astro', contents: COMPONENT_ASTRO(input) },
      ...common,
    ];
  }
  return [
    { path: 'chatly/identity.mjs', contents: IDENTITY_EXPRESS(input) },
    { path: 'chatly/snippet.html', contents: SNIPPET_EXPRESS(input) },
    ...common,
  ];
}
